Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <cstdio>
#include <vector>
#include <algorithm>

const long long MOD1 = 998244353;
const long long MOD2 = 1000000007;
const long long BASE = 1000000;

int n, tot, sum[15], ans;
std::vector<long long> vec[15];

void dfs1(int k, long long num) {
    if (k == 7) return;
    tot++;
    long long val = ((tot - num) % MOD1 + MOD1) % MOD1;
    vec[k].push_back(val);
    sum[k] = (sum[k] + val) % MOD2;
    for (int i = 0; i <= 9; ++i) {
        dfs1(k + 1, num * 10 + i);
    }
}

void dfs2(long long x) {
    if (x > n) return;
    if (x * BASE + BASE - 1 <= n && x * BASE * 10 > n) {
        long long currentTotal = tot;
        for (int i = 0, mul = 1; i <= 6; ++i, mul *= 10) {
            int sz = (int)vec[i].size();
            long long dif = ((currentTotal - x * mul) % MOD1 + MOD1) % MOD1;
            int pos = (int)(std::lower_bound(vec[i].begin(), vec[i].end(), (long long)(MOD1 - dif)) - vec[i].begin());
            ans = (ans + dif * sz + sum[i]) % MOD2;
            ans = (ans - (long long)MOD1 * (sz - pos) % MOD2 + MOD2) % MOD2;
            tot += sz;
        }
        return;
    }
    tot++;
    ans = (ans + ((tot - x) % MOD1 + MOD1) % MOD1) % MOD2;
    for (int i = 0; i <= 9; ++i) {
        dfs2(x * 10 + i);
    }
}

int main() {
    scanf("%d", &n);
    dfs1(0, 0);
    for (int i = 0; i <= 7; ++i) {
        std::sort(vec[i].begin(), vec[i].end());
    }
    tot = 0;
    for (int i = 1; i <= 9; ++i) {
        dfs2(i);
    }
    printf("%lld\n", ans);
    return 0;
}
